<?php
if (!defined('ABSPATH')) { exit; }
/** Fournisseurs, achats reçus et règlements fournisseurs. */
final class FKC_Purchases_API {
 private static function t($n){global $wpdb;return in_array($n,array('users','tenants','branches','members','permissions','branch_access','invitations','audit_logs','sessions'),true)?'bta_'.$n:$wpdb->prefix.'bta_'.$n;}
 private static function err($c,$m,$s=400){return new WP_Error($c,$m,array('status'=>$s));}
 private static function auth($r,$tenant,$perm){
  $h=$r->get_header('authorization');if(!$h&&isset($_SERVER['HTTP_AUTHORIZATION']))$h=wp_unslash($_SERVER['HTTP_AUTHORIZATION']);
  if(!is_string($h)||!preg_match('/^Bearer\s+([a-fA-F0-9]{64})$/',$h,$m))return self::err('bta_unauthenticated','Connexion requise.',401);
  global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT s.user_id,u.status FROM '.self::t('sessions').' s JOIN '.self::t('users').' u ON u.id=s.user_id WHERE s.token_hash=%s AND s.expires_at>%s LIMIT 1',hash('sha256',$m[1]),gmdate('Y-m-d H:i:s')),ARRAY_A);
  if(!$s||$s['status']!=='ACTIVE')return self::err('bta_unauthenticated','Session invalide ou expirée.',401);
  $mem=$wpdb->get_row($wpdb->prepare("SELECT role FROM ".self::t('members')." WHERE tenant_id=%d AND user_id=%d AND status='ACTIVE' LIMIT 1",$tenant,$s['user_id']),ARRAY_A);
  if(!$mem)return self::err('bta_forbidden','Accès refusé.',403);
  $map=array('OWNER'=>array('purchases.read','purchases.create'),'ADMIN'=>array('purchases.read','purchases.create'),'MANAGER'=>array('purchases.read','purchases.create'),'CASHIER'=>array());
  if(!in_array($perm,$map[$mem['role']]??array(),true))return self::err('bta_forbidden','Permission insuffisante.',403);
  return array('user_id'=>(int)$s['user_id']);
 }
 private static function page($r,$sql,$args,$key) {
  global $wpdb;$page=max(1,(int)$r->get_param('page'));$limit=min(100,max(1,(int)($r->get_param('per_page')?:100)));
  $total=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM ('.$sql.') bta_page_count',$args));
  $rows=$wpdb->get_results($wpdb->prepare($sql.' LIMIT %d OFFSET %d',array_merge($args,array($limit,($page-1)*$limit))),ARRAY_A);
  return array('success'=>true,$key=>$rows,'pagination'=>array('page'=>$page,'per_page'=>$limit,'total'=>$total,'pages'=>(int)ceil($total/$limit)));
 }
 public static function boot(){add_action('rest_api_init',array(__CLASS__,'routes'));}
 public static function routes(){
  register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/suppliers',array(array('methods'=>'GET','callback'=>array(__CLASS__,'suppliers'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'supplier_create'),'permission_callback'=>'__return_true')));
  register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/purchases',array(array('methods'=>'GET','callback'=>array(__CLASS__,'purchases'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'purchase_create'),'permission_callback'=>'__return_true')));
  register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/purchases/(?P<purchase_id>\d+)/payments',array('methods'=>'POST','callback'=>array(__CLASS__,'payment_create'),'permission_callback'=>'__return_true'));
 }
 public static function suppliers($r){$tenant=(int)$r['tenant_id'];$a=self::auth($r,$tenant,'purchases.read');if(is_wp_error($a))return $a;global $wpdb;$q=sanitize_text_field((string)$r->get_param('q'));$sql='SELECT id,name,phone,email,address,notes,status,created_at FROM '.self::t('suppliers').' WHERE tenant_id=%d';$args=array($tenant);if($q!==''){$sql.=' AND (name LIKE %s OR phone LIKE %s OR email LIKE %s)';$like='%'.$wpdb->esc_like($q).'%';array_push($args,$like,$like,$like);}$sql.=' ORDER BY id DESC';return self::page($r,$sql,$args,'suppliers');}
 public static function supplier_create($r){$tenant=(int)$r['tenant_id'];$a=self::auth($r,$tenant,'purchases.create');if(is_wp_error($a))return $a;$name=sanitize_text_field((string)$r->get_param('name'));if(strlen($name)<2)return self::err('bta_invalid_supplier','Le nom du fournisseur est obligatoire.');global $wpdb;$now=gmdate('Y-m-d H:i:s');$ok=$wpdb->insert(self::t('suppliers'),array('tenant_id'=>$tenant,'name'=>$name,'phone'=>sanitize_text_field((string)$r->get_param('phone')),'email'=>sanitize_email((string)$r->get_param('email')),'address'=>sanitize_textarea_field((string)$r->get_param('address')),'notes'=>sanitize_textarea_field((string)$r->get_param('notes')),'status'=>'ACTIVE','created_at'=>$now,'updated_at'=>$now));if(!$ok)return self::err('bta_supplier_create_failed',$wpdb->last_error?:'Création impossible.',500);return new WP_REST_Response(array('success'=>true,'supplier'=>array('id'=>(int)$wpdb->insert_id,'name'=>$name)),201);}
 public static function purchases($r){$tenant=(int)$r['tenant_id'];$a=self::auth($r,$tenant,'purchases.read');if(is_wp_error($a))return $a;global $wpdb;$page=max(1,(int)$r->get_param('page'));$limit=min(100,max(1,(int)($r->get_param('per_page')?:25)));$branch=absint($r->get_param('branch_id'));$t=self::t('purchases');$sql="SELECT id,branch_id,supplier_id,preorder_id,reference,status,currency,exchange_rate,subtotal,fees,total,paid,(total-paid) AS balance,created_at FROM {$t} WHERE tenant_id=%d";$args=array($tenant);if($branch){$sql.=' AND branch_id=%d';$args[]=$branch;}$sql.=' ORDER BY id DESC LIMIT %d OFFSET %d';$args[]=$limit;$args[]=($page-1)*$limit;$rows=$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A);$count_sql="SELECT COUNT(*) FROM {$t} WHERE tenant_id=%d";$count_args=array($tenant);if($branch){$count_sql.=' AND branch_id=%d';$count_args[]=$branch;}$total=(int)$wpdb->get_var($wpdb->prepare($count_sql,$count_args));return rest_ensure_response(array('success'=>true,'purchases'=>$rows,'pagination'=>array('page'=>$page,'per_page'=>$limit,'total'=>$total,'pages'=>(int)ceil($total/$limit))));}
 public static function purchase_create($r){$tenant=(int)$r['tenant_id'];$a=self::auth($r,$tenant,'purchases.create');if(is_wp_error($a))return $a;$branch=absint($r->get_param('branch_id'));$supplier=absint($r->get_param('supplier_id'));$ref=sanitize_text_field((string)$r->get_param('reference'));$currency=strtoupper((string)($r->get_param('currency')?:'USD'));$rate=(float)($r->get_param('exchange_rate')?:1);$items=$r->get_param('items');if(!$branch||strlen($ref)<2||!in_array($currency,array('USD','CDF'),true)||$rate<=0||!is_array($items)||!count($items))return self::err('bta_invalid_purchase','Établissement, référence, devise, taux et articles requis.');global $wpdb;if(!$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('branches')." WHERE id=%d AND tenant_id=%d AND status='ACTIVE'",$branch,$tenant)))return self::err('bta_invalid_branch','Établissement introuvable.',404);if($supplier&&!$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('suppliers')." WHERE id=%d AND tenant_id=%d AND status='ACTIVE'",$supplier,$tenant)))return self::err('bta_invalid_supplier','Fournisseur introuvable.',404);
  $clean=array();$subtotal=0;foreach($items as $it){$pid=absint($it['product_id']??0);$qty=(float)($it['quantity']??0);$cost=(float)($it['unit_cost']??0);if(!$pid||$qty<=0||$cost<0||!$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('products').' WHERE id=%d AND tenant_id=%d AND status=\'ACTIVE\'',$pid,$tenant)))return self::err('bta_invalid_purchase_item','Produit, quantité ou coût invalide.');$line=$qty*$cost;$subtotal+=$line;$clean[]=array($pid,$qty,$cost,$line);}
  $fees=max(0,(float)$r->get_param('fees'));$total=$subtotal+$fees;$paid=max(0,(float)$r->get_param('paid'));if($paid>$total)return self::err('bta_invalid_payment','Le paiement dépasse le total de l’achat.');$now=gmdate('Y-m-d H:i:s');$wpdb->query('START TRANSACTION');$ok=$wpdb->insert(self::t('purchases'),array('tenant_id'=>$tenant,'branch_id'=>$branch,'supplier_id'=>$supplier?:null,'preorder_id'=>absint($r->get_param('preorder_id'))?:null,'reference'=>$ref,'status'=>'RECEIVED','currency'=>$currency,'exchange_rate'=>$rate,'subtotal'=>$subtotal,'fees'=>$fees,'total'=>$total,'paid'=>$paid,'notes'=>sanitize_textarea_field((string)$r->get_param('notes')),'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_purchase_failed',$wpdb->last_error?:'Achat impossible.',409);}$id=(int)$wpdb->insert_id;
  foreach($clean as $it){$wpdb->insert(self::t('purchase_items'),array('tenant_id'=>$tenant,'purchase_id'=>$id,'product_id'=>$it[0],'quantity'=>$it[1],'unit_cost'=>$it[2],'line_total'=>$it[3],'created_at'=>$now));$st=self::t('stock');$sid=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$st} WHERE tenant_id=%d AND branch_id=%d AND product_id=%d",$tenant,$branch,$it[0]));if($sid)$wpdb->query($wpdb->prepare("UPDATE {$st} SET quantity=quantity+%f,updated_at=%s WHERE id=%d",$it[1],$now,$sid));else $wpdb->insert($st,array('tenant_id'=>$tenant,'branch_id'=>$branch,'product_id'=>$it[0],'quantity'=>$it[1],'updated_at'=>$now));$wpdb->insert(self::t('stock_movements'),array('tenant_id'=>$tenant,'branch_id'=>$branch,'product_id'=>$it[0],'movement_type'=>'PURCHASE_RECEIPT','quantity'=>$it[1],'reference_type'=>'purchase','reference_id'=>$id,'notes'=>'Réception achat '.$ref,'created_by'=>$a['user_id'],'created_at'=>$now));}
  if($paid>0)$wpdb->insert(self::t('payments'),array('tenant_id'=>$tenant,'branch_id'=>$branch,'entity_type'=>'PURCHASE','entity_id'=>$id,'payment_type'=>'SUPPLIER_PAYMENT','amount'=>$paid,'currency'=>$currency,'exchange_rate'=>$rate,'method'=>sanitize_text_field((string)($r->get_param('payment_method')?:'CASH')),'reference'=>sanitize_text_field((string)$r->get_param('payment_reference')),'notes'=>'Paiement initial achat '.$ref,'created_by'=>$a['user_id'],'created_at'=>$now));if($wpdb->last_error){$wpdb->query('ROLLBACK');return self::err('bta_purchase_transaction_failed','Erreur pendant l’enregistrement de l’achat.',500);}$wpdb->query('COMMIT');return new WP_REST_Response(array('success'=>true,'purchase'=>array('id'=>$id,'reference'=>$ref,'subtotal'=>$subtotal,'fees'=>$fees,'total'=>$total,'paid'=>$paid,'balance'=>$total-$paid,'currency'=>$currency,'stock_updated'=>true)),201);
 }
 public static function payment_create($r){$tenant=(int)$r['tenant_id'];$a=self::auth($r,$tenant,'purchases.create');if(is_wp_error($a))return $a;$id=(int)$r['purchase_id'];$amount=(float)$r->get_param('amount');$method=sanitize_text_field((string)($r->get_param('method')?:'CASH'));if($amount<=0)return self::err('bta_invalid_payment','Montant invalide.');global $wpdb;$p=self::t('purchases');$wpdb->query('START TRANSACTION');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$p} WHERE id=%d AND tenant_id=%d FOR UPDATE",$id,$tenant),ARRAY_A);if(!$row){$wpdb->query('ROLLBACK');return self::err('bta_purchase_not_found','Achat introuvable.',404);}if($amount>(float)$row['total']-(float)$row['paid']){$wpdb->query('ROLLBACK');return self::err('bta_payment_exceeds_balance','Le paiement dépasse le solde fournisseur.');}$now=gmdate('Y-m-d H:i:s');$ok=$wpdb->insert(self::t('payments'),array('tenant_id'=>$tenant,'branch_id'=>$row['branch_id'],'entity_type'=>'PURCHASE','entity_id'=>$id,'payment_type'=>'SUPPLIER_PAYMENT','amount'=>$amount,'currency'=>$row['currency'],'exchange_rate'=>$row['exchange_rate'],'method'=>$method,'reference'=>sanitize_text_field((string)$r->get_param('reference')),'notes'=>sanitize_textarea_field((string)$r->get_param('notes')),'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_payment_failed','Paiement non enregistré.',500);}$paid=(float)$row['paid']+$amount;$wpdb->update($p,array('paid'=>$paid),array('id'=>$id,'tenant_id'=>$tenant));$wpdb->query('COMMIT');return rest_ensure_response(array('success'=>true,'purchase_id'=>$id,'paid'=>$paid,'balance'=>(float)$row['total']-$paid,'currency'=>$row['currency']));}
}
